package com.ml.tblandroidtxt;import org.json.JSONArray;import org.json.JSONObject;
/** Chapter-level independent synthesis, still created before REPORT_L1 becomes visible. */
public final class EditorialL3VoiceAuditContract {public static String schema(){return "{\"chapterId\":\"string\",\"findings\":[{\"id\":\"string\",\"scenes\":\"string\",\"finding\":\"string\",\"impact\":\"string\"}],\"crossSceneVoiceAudit\":\"CLOSED\",\"status\":\"CLOSED\"}";}public static String validate(String text,String chapterId){try{JSONObject r=new JSONObject(text);if(!chapterId.equals(r.optString("chapterId"))||!"CLOSED".equals(r.optString("crossSceneVoiceAudit"))||!"CLOSED".equals(r.optString("status")))return "Cross-scene voice audit is not closed";JSONArray a=r.optJSONArray("findings");if(a==null)return "Missing cross-scene findings";for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null||blank(x.optString("id"))||blank(x.optString("scenes"))||blank(x.optString("finding"))||blank(x.optString("impact")))return "Incomplete cross-scene finding";}return null;}catch(Exception e){return "Invalid cross-scene voice audit JSON";}}private static boolean blank(String x){return x==null||x.trim().isEmpty();}private EditorialL3VoiceAuditContract(){}}
